package com.example.riskplatform.service;import com.example.riskplatform.entity.OperationLog;import com.example.riskplatform.mapper.OperationLogMapper;import com.example.riskplatform.security.CurrentUserService;import jakarta.servlet.http.HttpServletRequest;import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Service;
@Service @RequiredArgsConstructor public class AuditService{private final OperationLogMapper mapper;private final CurrentUserService current;private final HttpServletRequest req;public void log(String a,String t,Long id,String d){OperationLog l=new OperationLog();l.setUserId(current.userId());l.setAction(a);l.setResourceType(t);l.setResourceId(id);l.setDetail(d);l.setIpAddress(req.getRemoteAddr());mapper.insert(l);}}
